from typing import Literal

from pydantic import BaseModel, Field, ValidationError


class ThemeCoding(BaseModel):
    theme: Literal["Price", "Service", "Product", "Other"]
    confidence: float = Field(ge=0, le=1)


replies = [
    '{"theme": "Price", "confidence": 0.8}',
    '{"theme": "Pricing", "confidence": 0.8}',
    'Here you go: {"theme": "Price", "confidence": 0.8}',
    '{"theme": "Service", "confidence": "0.7"}',
]
for reply in replies:
    try:
        print(ThemeCoding.model_validate_json(reply).theme)
    except ValidationError as err:
        print("invalid:", err.errors()[0]["type"])

