def code_with_retry(call_model, messages):
    history = list(messages)
    reply = ""
    for attempt in range(1, MAX_ATTEMPTS + 1):
        reply = call_model(history)
        try:
            coding = ThemeCoding.model_validate_json(reply)
        except ValidationError as err:
            history += [
                {"role": "assistant", "content": reply},
                {"role": "user", "content": f"Invalid: {err.errors()[0]['msg']}"},
            ]
            continue
        return CodingResult(status="coded", coding=coding, attempts=attempt, raw_reply=reply)
    return CodingResult(status="coded", coding=ThemeCoding(theme="Other", confidence=0.0), attempts=MAX_ATTEMPTS, raw_reply=reply)

